#include <iostream>

void swap_value(int x, int y) {
    std::cout << "inside: &x=" << &x << ", &y=" << &y << '\n';

    int temp = x;
    x = y;
    y = temp;

    std::cout << "inside: x=" << x << ", y=" << y << '\n';
}


void swap_pointer(int* x, int* y) {
    std::cout << "pointer: x=" << x << ", y=" << y << '\n';
    std::cout << "pointer: &x=" << &x << ", &y=" << &y << '\n';

    int temp = *x;
    *x = *y;
    *y = temp;

    std::cout << "pointer: *x=" << *x << ", *y=" << *y << '\n';
}

void swap_reference(int& x, int& y) {
    std::cout << "reference: &x=" << &x << ", &y=" << &y << '\n';

    int temp = x;
    x = y;
    y = temp;

    std::cout << "reference: x=" << x << ", y=" << y << '\n';
}

int main() {
{ int a = -4; int b = 0; swap_value(a, b); std::cout << "CHECK|negative_zero_value|" << a << "|" << b << "\n"; }
{ int a = -4; int b = 0; swap_pointer(&a, &b); std::cout << "CHECK|negative_zero_pointer|" << a << "|" << b << "\n"; }
{ int a = -4; int b = 0; swap_reference(a, b); std::cout << "CHECK|negative_zero_reference|" << a << "|" << b << "\n"; }
{ int a = 5; int b = 5; swap_value(a, b); std::cout << "CHECK|equal_value|" << a << "|" << b << "\n"; }
{ int a = 5; int b = 5; swap_pointer(&a, &b); std::cout << "CHECK|equal_pointer|" << a << "|" << b << "\n"; }
{ int a = 5; int b = 5; swap_reference(a, b); std::cout << "CHECK|equal_reference|" << a << "|" << b << "\n"; }
{ int a = 7; swap_pointer(&a, &a); std::cout << "CHECK|alias_pointer|" << a << "\n"; }
{ int a = 7; swap_reference(a, a); std::cout << "CHECK|alias_reference|" << a << "\n"; }
return 0;
}
